import { once } from "lodash-es";

import { exec } from "./process";
import type { YarnWorkspaceItem } from "./types";
import {
  PackageList as GeneratedPackageList,
  type PackageName,
} from "./workspace.gen";
// Static import: workspace.gen.ts is committed and regenerated by `myoxus-cli
// init`. A dynamic `await import(new URL(..., import.meta.url).href)` breaks
// under Vitest's vite-node transport, where `import.meta.url` is served as an
// `http://` URL and Node's ESM loader rejects non-file/data schemes
// (ERR_UNSUPPORTED_ESM_URL_SCHEME). Static imports are resolved by the bundler
// /test transformer, so they sidestep that scheme restriction entirely.

export const PackageList = GeneratedPackageList;
export type { PackageName };

export const yarnList = once(() => {
  const output = exec("", "yarn workspaces list -v --json", { silent: true });

  let packageList = JSON.parse(
    `[${output.trim().replace(/\r\n|\n/g, ",")}]`,
  ) as YarnWorkspaceItem[];

  packageList.forEach((p) => {
    p.location = p.location.replaceAll(/\\/g, "/");
    delete p["mismatchedWorkspaceDependencies"];
  });

  // ignore root package
  return packageList.filter((p) => p.location !== ".");
});
